static int rtl8153_disable(struct r8152 *tp)
{
	int ret, err = 0;

	ret = r8153_aldps_en(tp, false);
	if (ret < 0)
		err = ret;
	ret = rtl_disable(tp);
	if (ret < 0)
		err = ret;
	ret = rtl_reset_bmu(tp);
	if (ret < 0)
		err = ret;
	ret = r8153_aldps_en(tp, true);

	if (err < 0)
		return err;
	else
		return ret;
}
